<?php
namespace Tests\Feature;use App\Models\ActivityLog;use App\Models\Admin;use App\Models\Employee;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class EmployeeAuditRegressionTest extends TestCase {use RefreshDatabase;public function test_employee_create_and_sensitive_update_create_safe_audit_evidence():void{$admin=Admin::create(['name'=>'HR','email'=>'hr@test.local','password'=>bcrypt('p'),'role'=>'super_admin']);Sanctum::actingAs($admin);$this->postJson('/api/v1/user-management/employees',['employee_id'=>'E1','nik'=>'N1','name'=>'E','department'=>'Ops','card_no'=>'4111222233334444'])->assertCreated();$employee=Employee::first();$this->assertDatabaseHas('activity_logs',['action'=>'create_employee','subject_id'=>$employee->id]);$this->putJson('/api/v1/user-management/employees/'.$employee->id,['employment_status'=>'INACTIVE','supervisor_id'=>null])->assertOk();$log=ActivityLog::where('action','update_employee')->latest('id')->firstOrFail();$this->assertStringNotContainsString('4111222233334444',$log->description);$this->assertStringNotContainsString('password',$log->description);}}
